using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Text;
using Microsoft.Win32;

namespace WindowsOptimizerForAll {
 public static class ChangeJournal {
  static readonly object Gate=new object();
  static string FilePath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"WindowsOptimizerForAll","change-journal.json");}}
  static RegistryKey Hive(string name){if(String.Equals(name,"HKLM",StringComparison.OrdinalIgnoreCase))return Registry.LocalMachine;if(String.Equals(name,"HKCU",StringComparison.OrdinalIgnoreCase))return Registry.CurrentUser;throw new InvalidOperationException("Unsupported registry hive.");}
  static RegistryValueSnapshot Capture(TrackedRegistryValue setting){if(String.Equals(setting.Hive,"POWER",StringComparison.OrdinalIgnoreCase))return new RegistryValueSnapshot{Hive=setting.Hive,Key=setting.Key,Name=setting.Name,Exists=true,Kind="String",Value=SystemActions.GetActivePowerScheme()};using(var key=Hive(setting.Hive).OpenSubKey(setting.Key,false)){if(key==null||!key.GetValueNames().Any(n=>String.Equals(n,setting.Name,StringComparison.OrdinalIgnoreCase)))return new RegistryValueSnapshot{Hive=setting.Hive,Key=setting.Key,Name=setting.Name,Exists=false};object value=key.GetValue(setting.Name,null,RegistryValueOptions.DoNotExpandEnvironmentNames);RegistryValueKind kind=key.GetValueKind(setting.Name);return new RegistryValueSnapshot{Hive=setting.Hive,Key=setting.Key,Name=setting.Name,Exists=true,Kind=kind.ToString(),Value=Encode(value,kind)};}}
  static string Encode(object value,RegistryValueKind kind){if(value==null)return "";if(kind==RegistryValueKind.Binary||kind==RegistryValueKind.None)return Convert.ToBase64String((byte[])value);if(kind==RegistryValueKind.MultiString)return String.Join("\n",(string[])value);return Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture);}
  static object Decode(RegistryValueSnapshot value,RegistryValueKind kind){if(kind==RegistryValueKind.Binary||kind==RegistryValueKind.None)return Convert.FromBase64String(value.Value??"");if(kind==RegistryValueKind.MultiString)return (value.Value??"").Split(new[]{'\n'},StringSplitOptions.None);if(kind==RegistryValueKind.DWord)return Int32.Parse(value.Value,System.Globalization.CultureInfo.InvariantCulture);if(kind==RegistryValueKind.QWord)return Int64.Parse(value.Value,System.Globalization.CultureInfo.InvariantCulture);return value.Value??"";}
  static bool Same(RegistryValueSnapshot a,RegistryValueSnapshot b){return a.Exists==b.Exists&&(!a.Exists||(String.Equals(a.Kind,b.Kind,StringComparison.Ordinal)&&String.Equals(a.Value,b.Value,StringComparison.Ordinal)));}
  static List<ChangeJournalEntry> Load(){try{if(!File.Exists(FilePath))return new List<ChangeJournalEntry>();using(var stream=File.OpenRead(FilePath)){var serializer=new DataContractJsonSerializer(typeof(List<ChangeJournalEntry>));return (List<ChangeJournalEntry>)serializer.ReadObject(stream)??new List<ChangeJournalEntry>();}}catch{return new List<ChangeJournalEntry>();}}
  static void Save(List<ChangeJournalEntry> entries){Directory.CreateDirectory(Path.GetDirectoryName(FilePath));string temp=FilePath+".tmp";using(var stream=File.Create(temp)){var serializer=new DataContractJsonSerializer(typeof(List<ChangeJournalEntry>));serializer.WriteObject(stream,entries);}if(File.Exists(FilePath))File.Replace(temp,FilePath,null);else File.Move(temp,FilePath);}
  public static IReadOnlyList<ChangeJournalEntry> GetEntries(){lock(Gate)return Load().OrderByDescending(x=>x.AppliedAtUtc).ToList().AsReadOnly();}
  public static void Apply(TweakItem item){var before=item.TrackedSettings.Select(Capture).ToList();Exception failure=null;try{item.Apply();}catch(Exception ex){failure=ex;}var after=item.TrackedSettings.Select(Capture).ToList();var entry=new ChangeJournalEntry{Id=Guid.NewGuid().ToString("N"),Name=item.Name,Description=item.Description,AppliedAtUtc=DateTime.UtcNow.ToString("o"),Reversible=before.Count>0,Before=before,After=after,Status=failure==null?Localization.T("Операция выполнена"):Localization.T("Ошибка: ")+failure.Message};lock(Gate){var all=Load();all.Add(entry);Save(all);}if(failure!=null)throw failure;}
  public static void RecordIrreversible(string name,string description){var entry=new ChangeJournalEntry{Id=Guid.NewGuid().ToString("N"),Name=name,Description=description,AppliedAtUtc=DateTime.UtcNow.ToString("o"),Reversible=false,Before=new List<RegistryValueSnapshot>(),After=new List<RegistryValueSnapshot>(),Status=Localization.T("Необратимая операция; приложение Windows удалено для текущего пользователя.")};lock(Gate){var all=Load();all.Add(entry);Save(all);}}
  public static string Verify(){var entries=GetEntries().Where(x=>!x.Restored).ToList();if(entries.Count==0)return Localization.T("Журнал пока пуст.");var lines=new List<string>();foreach(var e in entries){if(e.After.Count==0){lines.Add(Localization.T(e.Name)+": "+Localization.T("изменение нельзя проверить по реестру"));continue;}bool matches=true;for(int i=0;i<e.After.Count;i++){if(!Same(Capture(new TrackedRegistryValue(e.After[i].Hive,e.After[i].Key,e.After[i].Name)),e.After[i])){matches=false;break;}}lines.Add(Localization.T(e.Name)+": "+(matches?Localization.T("состояние совпадает с записанным после применения"):Localization.T("обнаружено расхождение с записанным состоянием")));}return String.Join(Environment.NewLine,lines.ToArray());}
  static void RestoreValue(RegistryValueSnapshot old){if(String.Equals(old.Hive,"POWER",StringComparison.OrdinalIgnoreCase)){SystemActions.SetActivePowerScheme(old.Value);return;}if(String.Equals(old.Hive,"HKLM",StringComparison.OrdinalIgnoreCase)&&old.Key.EndsWith(@"\Services\SysMain",StringComparison.OrdinalIgnoreCase)&&String.Equals(old.Name,"Start",StringComparison.OrdinalIgnoreCase)&&old.Exists){SystemActions.RestoreServiceStartup(Int32.Parse(old.Value,System.Globalization.CultureInfo.InvariantCulture));return;}using(var key=Hive(old.Hive).CreateSubKey(old.Key)){if(!old.Exists){key.DeleteValue(old.Name,false);return;}RegistryValueKind kind=(RegistryValueKind)Enum.Parse(typeof(RegistryValueKind),old.Kind);key.SetValue(old.Name,Decode(old,kind),kind);}}
  public static string RestoreAll(){lock(Gate){var all=Load();int restored=0,conflict=0,skipped=0;foreach(var entry in all.Where(x=>!x.Restored&&x.Reversible).OrderByDescending(x=>x.AppliedAtUtc)){bool matches=true;for(int i=0;i<entry.After.Count;i++){if(!Same(Capture(new TrackedRegistryValue(entry.After[i].Hive,entry.After[i].Key,entry.After[i].Name)),entry.After[i])){matches=false;break;}}if(!matches){conflict++;continue;}for(int i=0;i<entry.Before.Count;i++)RestoreValue(entry.Before[i]);entry.Restored=true;entry.Status=Localization.T("Исходное состояние восстановлено");restored++;}skipped=all.Count(x=>!x.Restored&&!x.Reversible);Save(all);return Localization.T("Восстановлено записей: ")+restored+". "+Localization.T("Конфликтов (не перезаписаны): ")+conflict+". "+Localization.T("Необратимых операций: ")+skipped+".";}}
 }
}
